push("🌹分类🌹",null,1)
    for(i in a){
        title=a[i].text()
        url=a[i].attr("href")
        size=0.25;
  url=String(url).replace("1/","{{page}}/").replace("1.html","{{page}}.html")
        push(title,url,size)
    };

 push("🌹排行🌹",null,1)
